function personFields(){const physical=$('#f-tipo').value==='Física',categories=[...document.querySelectorAll('[name="categorias"]:checked')].map(e=>e.value);document.querySelector('[data-field="inss"]')?.classList.toggle('hidden',!physical);for(const k of ['seguradora','seguradora_cnpj','apolice_rctrc','apolice_rcdc'])document.querySelector(`[data-field="${k}"]`).classList.toggle('hidden',!categories.includes('Cliente'));for(const k of ['rntrc','tipo_proprietario'])document.querySelector(`[data-field="${k}"]`).classList.toggle('hidden',!categories.includes('Proprietário'));const labels={nome:physical?'Nome completo':'Razão social',documento:physical?'CPF':'CNPJ',inscricao:physical?'RG':'Inscrição estadual',fantasia:physical?'Apelido':'Nome fantasia',data:physical?'Nascimento':'Abertura'};for(const [k,label]of Object.entries(labels))document.querySelector(`[data-field="${k}"] label`).textContent=label;document.querySelectorAll('.form-section').forEach(section=>{section.hidden=[...section.querySelectorAll('.field')].every(field=>field.classList.contains('hidden'))})}
function readForm(){for(const el of document.querySelectorAll("[data-lookup]")){const text=el.querySelector(".lookup-text"),id=el.querySelector("input[type=hidden]");if(!text.disabled&&text.value.trim()&&!id.value){text.focus();throw new Error("Selecione um resultado da pesquisa ou limpe o campo.")}}const d={};for(const f of state.schema[formContext.module].fields){if(formContext.module==='ciot'&&['irrf','sest','senat','sest_senat','inss','iss','outros_tributos'].includes(f.key)&&!state.approve)continue;if(f.type==='readonly'||(['inss_desconto','sest_desconto','senat_desconto'].includes(f.key)&&!state.approve))continue;if(formContext.module==='usuarios'&&['abas','ocultar'].includes(f.key)){d[f.key]=[...document.querySelectorAll('[data-tab-permission]')].filter(x=>x.value===(f.key==='abas'?'allow':'deny')).map(x=>x.dataset.tabPermission);continue}if(f.type==='checks')d[f.key]=[...document.querySelectorAll(`[name="${f.key}"]:checked`)].map(x=>x.value);else if(formContext.module==='usuarios'&&['abas','ocultar'].includes(f.key))d[f.key]=[...document.querySelectorAll('[data-tab-permission]')].filter(x=>x.value===(f.key==='abas'?'allow':'deny')).map(x=>x.dataset.tabPermission);else if(formContext.module==='ciot'&&f.type==='rows'&&['documentos','pagamentos'].includes(f.key))d[f.key]=[...document.querySelectorAll(`[data-rows="${f.key}"] .ciot-repeat-row`)].map(row=>Object.fromEntries([...row.querySelectorAll('[data-cell]')].map(x=>[x.dataset.cell,x.value]))).filter(row=>Object.values(row).some(Boolean));else if(f.type==='rows'&&f.key==='contatos')d[f.key]=[...document.querySelectorAll('[data-rows="contatos"] .contact-row')].map(row=>[...row.querySelectorAll('input')].map(e=>e.value)).filter(row=>row.some(Boolean));else if(f.type==='rows')d[f.key]=[...document.querySelectorAll(`[data-rows="${f.key}"] .row-value`)].map(x=>x.value.split(';').map(v=>v.trim())).filter(x=>x.some(Boolean));else{if(!$('#f-'+f.key))continue;const v=$('#f-'+f.key)?.value??'';d[f.key]=['number','money','offer'].includes(f.type)&&v!==''?Number(v):f.type==='ref'&&v?Number(v):v}}return d}
async function driverVehicles(){const id=$('#f-motorista').value;if(!id){setField('telefone_motorista','');loadDriverPerformance('');return;}loadDriverPerformance(id);const before=Object.fromEntries(['tracao','carreta','carreta2'].map(k=>[k,$('#f-'+k)?.value||'']));try{const op=await api('operations?view='+(['dashboard','painel','tracking'].find(k=>state.tabs.includes(k))||'dashboard')),d=op.motoristas.find(r=>r.id===Number(id));if($('#f-motorista')?.value!==id)return;if(d)for(const k of ['tracao','carreta','carreta2','telefone_motorista'])if(k==='telefone_motorista'||(!before[k]&&$('#f-'+k)?.value===before[k]))setField(k,k==='telefone_motorista'?(d.celular||d.telefone||''):d[k]||'')}catch(e){toast('Preenchimento automático requer acesso a Motoristas; selecione os veículos manualmente.')}}
async function generateOC(id,accept=false){try{const existing=rows.find(r=>r.id===id)?.oc_id;if(!accept&&!existing&&!await dgConfirm('Gerar uma única OC para esta programação? Confira o motorista, o veículo e os dados da viagem.'))return;const result=await api('generate-oc',{id,accept_warnings:accept});if(result.needs_confirmation){if(await dgConfirm('Alertas:\n'+result.warnings.join('\n')+'\n\nContinuar e gerar a OC?'))return generateOC(id,true);return}toast(result.existing?'Esta programação já possui a OC #'+result.id:'OC #'+result.id+' criada.');if(state.tabs.includes('oc')){await navigate('oc');await edit(rows.find(r=>r.id===result.id))}else await navigate(current)}catch(e){toast(e.message,true)}}
async function createDriver(cap){if(!state.tabs.includes('motoristas')){toast('Seu perfil não tem acesso ao cadastro de motoristas.',true);return}await edit({nome:cap.nome,telefone:cap.telefone,captacao:cap.id,status:'Ativo'},'motoristas')}
async function fillFromOC(){try{const id=$('#f-oc').value;if(!id)throw new Error('Selecione uma OC primeiro.');const op=await api('operations?view='+(['dashboard','painel','tracking'].find(k=>state.tabs.includes(k))||'dashboard')),oc=op.oc.find(r=>r.id===Number(id)),p=op.programacao.find(r=>r.id===oc?.programacao);if(!p)throw new Error('Programação não encontrada.');const vals={motorista:p.motorista,tracao:p.tracao,carreta:p.carreta,carreta2:p.carreta2,produto:p.produto,peso:p.peso,quantidade:p.quantidade,remetente:p.origem,destinatario:p.destino,tomador:p.cliente,pagador:p.cliente,contratante:p.cliente,frete:p.valor_cliente,frete_agregado:p.frete_agregado,pedagio:p.pedagio,contrato_valor:p.frete_agregado,observacoes:p.observacoes};for(const [k,v]of Object.entries(vals))if($('#f-'+k)&&v!==undefined)setField(k,v);toast('Dados da OC preenchidos. Confira os demais campos antes de salvar.')}catch(e){toast(e.message,true)}}
async function exportRecords(){try{const data=await api('export?module='+current);download(JSON.stringify(data,null,2),current+'.json','application/json')}catch(e){toast(e.message,true)}}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function pickFile(accept){return new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>resolve(input.files[0]);input.click()})}
function parseCSV(text){const lines=[],row=[];let value='',quote=false;const sep=text.split('\n')[0].includes(';')?';':',';for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quote&&text[i+1]==='"'){value+='"';i++}else quote=!quote}else if(ch===sep&&!quote){row.push(value);value=''}else if(ch==='\n'&&!quote){row.push(value.replace(/\r$/,''));lines.push(row.splice(0));value=''}else value+=ch}if(value||row.length){row.push(value.replace(/\r$/,''));lines.push(row)}const header=lines.shift().map(v=>v.replace(/^\uFEFF/,'').trim());return lines.filter(r=>r.some(Boolean)).map(r=>Object.fromEntries(header.map((k,i)=>[k,r[i]||''])))}
async function importDialog(){const file=await pickFile('.json,.csv');if(!file)return;try{const text=await file.text(),data=file.name.endsWith('.csv')?parseCSV(text):JSON.parse(text),records=Array.isArray(data)?data:data.records;if(!Array.isArray(records))throw new Error('Formato inválido. Use array JSON ou CSV com os nomes dos campos.');if(!await dgConfirm(`Importar ${records.length} registros em ${titles[current]}? Duplicados serão avisados e ignorados.`))return;const result=await api('import',{module:current,records});await navigate(current);const failed=result.filter(r=>r.error);toast(`${result.length-failed.length} importados; ${failed.length} não importados.`);if(failed.length)download(JSON.stringify(failed,null,2),'resultado-importacao.json','application/json')}catch(e){toast(e.message,true)}}
async function xmlImport(){const file=await pickFile('.xml');if(!file)return;try{const doc=new DOMParser().parseFromString(await file.text(),'application/xml');if(doc.querySelector('parsererror'))throw new Error('XML inválido.');const tag=(name)=>[...doc.getElementsByTagNameNS('*',name)][0]?.textContent||'';const name=formContext.module;const valueCarga=tag('vCarga')||tag('vNF'),peso=tag('qCarga')||tag('pesoB'),ncm=tag('NCM'),produto=tag('proPred')||tag('xProd');let changes={produto,peso,valor_carga:valueCarga};if(name==='cte')changes.valor_total=tag('vTPrest');if(name==='mdfe')changes.ncm=ncm;changes=Object.fromEntries(Object.entries(changes).filter(([k,v])=>v&&$('#f-'+k)));const nfe=[...doc.getElementsByTagNameNS('*','infNFe')].map(x=>x.getAttribute('Id')?.replace(/^NFe/,''));const cte=[...doc.getElementsByTagNameNS('*','infCte')].map(x=>x.getAttribute('Id')?.replace(/^CTe/,''));const keys=[...nfe,...cte].filter(Boolean);if(!Object.keys(changes).length&&!keys.length)throw new Error('Nenhum campo reconhecido neste XML.');const preview=Object.entries(changes).map(([k,v])=>k+': '+v).join('\n')+(keys.length?'\nChaves:\n'+keys.join('\n'):'');if(!await dgConfirm('Confira os dados extraídos:\n\n'+preview+'\n\nAplicar ao rascunho?'))return;for(const[k,v]of Object.entries(changes))$('#f-'+k).value=v;const btn=$('[data-add-row="documentos"]');if(btn){keys.forEach(k=>btn.insertAdjacentHTML('beforebegin',rowHTML(k)));wireRemoveRows()}toast('XML aplicado. Revise os campos antes de salvar.')}catch(e){toast(e.message,true)}}
function renderOperations(){if(current==='sla')return slaView();if(current==='tracking')return trackingView();if(current==='painel')return panelView();dashboardView()}
function activeTrips(){return operations.programacao.filter(p=>!['Finalizada','Cancelada'].includes(p.status))}
function summaryTable(list){return list.length?`<table><thead><tr><th>Viagem</th><th>Motorista / Veículo</th><th>Carregamento</th><th>Status</th></tr></thead><tbody>${list.map(p=>`<tr><td><strong>${esc(p.lh_trip||'#'+p.id)}</strong><br><small class="muted">${esc(ref('pessoas',p.origem))} → ${esc(ref('pessoas',p.destino))}</small></td><td>${esc(ref('motoristas',p.motorista))}<br><small class="muted">${esc(ref('veiculos',p.tracao))}</small></td><td>${esc(datefmt(p.carregamento))}</td><td>${badge(p.status)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">'+icon('veiculos')+'<p>Sua operação começa aqui.</p><small>Cadastre pessoas, motoristas e veículos para programar uma viagem.</small></div>'}
function dashboardView(){const active=activeTrips(),moving=operations.oc.filter(o=>o.status==='Em Viagem'),finished=operations.oc.filter(o=>o.status==='Finalizada'),missing=active.filter(p=>!p.motorista);const statuses=['Captada','Sem motorista','Aberta','Em Carregamento','Em Viagem','Finalizada'];const vals=statuses.map(s=>operations.programacao.filter(p=>p.status===s).length),max=Math.max(1,...vals);$('#view').innerHTML=`<div class="content"><div class="eyebrow">Visão geral da operação</div><h2>Uma operação conectada.</h2><p class="muted">Acompanhe sua transportadora, da captação à entrega.</p><div class="metrics">${[['Viagens abertas',active.length,'Programações em andamento','programacao'],['Em viagem',moving.length,'A caminho do destino','veiculos'],['Sem motorista',missing.length,'Aguardando confirmação','motoristas'],['Finalizadas',finished.length,'Entregas concluídas','check']].map(([label,value,note,ico])=>`<div class="metric"><div style="display:flex;justify-content:space-between"><small>${label}</small>${icon(ico)}</div><div class="value">${value}</div><small>${note}</small></div>`).join('')}</div><div class="split"><section class="card"><div class="cardhead"><h3>Últimas programações</h3>${badge(active.length+' ativas')}</div><div class="tablewrap">${summaryTable(operations.programacao.slice(-7).reverse())}</div></section><section class="card"><div class="cardhead"><h3>Status das viagens</h3><small class="muted">Visão acumulada</small></div><div class="chart">${statuses.map((s,i)=>`<div class="barcol"><strong>${vals[i]}</strong><div class="bar" style="height:${Math.round(vals[i]/max*130)}px"></div>${s}</div>`).join('')}</div><div style="padding:20px;color:var(--muted);font-size:11px">Atualização operacional a cada 10 segundos.</div></section></div></div>`;wireSlaActions()}
