setInterval(async()=>{if(!state||document.hidden)return;if(current==='tracking'&&Date.now()-lastTrackingFetch<300000)return;try{const view=['dashboard','tracking','painel','sla'].includes(current)?current:['dashboard','tracking','painel'].find(k=>state.tabs.includes(k));if(!view)return;operations=await api('operations?view='+view);if(current==='tracking')lastTrackingFetch=Date.now();if(alertEnabled&&activeTrips().some(p=>panelStatus(p)==='No-show')&&Date.now()-lastAlarm>=300000){sound();lastAlarm=Date.now()}if(['dashboard','tracking','painel','sla'].includes(current)&&!formContext&&!$('#sla-filters')?.contains(document.activeElement))renderOperations()}catch(e){}},10000);


async function documentImport(){const file=await pickFile('.pdf,.xlsx,.csv');if(!file)return;try{if(file.size>3000000)throw new Error('Limite de 3 MB por arquivo.');const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));const result=await api('import-document',{module:formContext.module,filename:file.name,content:btoa(raw)});const preview=JSON.stringify(result.fields,null,2)+'\nChaves: '+result.keys.join(', ');if(!await dgConfirm('Dados extraídos. Revise antes de aplicar:\n'+preview+'\n\nAplicar ao formulário?'))return;for(const[k,v]of Object.entries(result.fields)){if($('#f-'+k))setField(k,v)}const btn=$('[data-add-row="documentos"]');if(btn){result.keys.forEach(k=>btn.insertAdjacentHTML('beforebegin',rowHTML(k)));wireRemoveRows()}toast(result.warning||'Dados aplicados. Confira todo o rascunho.');}catch(e){toast(e.message,true)}}
