function formSections(m,d){const schema=state.schema[m].fields.filter(f=>!f.key.startsWith('sla_')).filter(f=>m!=='programacao'||d.id||['lh_trip','cliente','valor_cliente','status','carregamento','eta_destino','origem','destino','observacoes'].includes(f.key)),definitions=sectionDefinitions[m]||[['Dados do cadastro','Preencha os campos e salve o registro.',m,schema.map(f=>f.key)]],used=new Set();let out=definitions.map(([title,subtitle,ico,keys],index)=>{const fields=keys.map(k=>schema.find(f=>f.key===k)).filter(Boolean);fields.forEach(f=>used.add(f.key));if(!fields.length)return '';return `<section class="form-section section-${m}-${index} ${''}" data-section="${title}"><div class="section-heading"><span class="section-icon">${icon(ico)}</span><div><h3>${esc(title)}</h3><p>${esc(subtitle)}</p></div>${m==='programacao'&&index===0?`<span class="section-status">${badge(d.status||'Captada')}</span>`:''}${m==='programacao'&&index===3&&state.financial?'<span class="access-label">Administrador / Financeiro</span>':''}</div><div class="section-fields">${fields.map(f=>fieldHTML(f,d)).join('')}${m==='programacao'&&index===1?`<div class="driver-hint wide" id="driver-hint">${icon('motoristas')} ${d.motorista?'Motorista vinculado.':'Motorista ainda não vinculado.'}</div>`:''}${m==='programacao'&&index===3&&state.financial?'<div class="margin-summary wide"><div><small>Margem bruta</small><strong id="margin-value">R$ 0,00</strong></div><span id="margin-percent">0,00%</span></div>':''}</div></section>`}).join('');const extra=schema.filter(f=>!used.has(f.key));if(extra.length)out+=`<section class="form-section"><div class="section-heading"><span class="section-icon">${icon('oc')}</span><h3>Informações complementares</h3></div><div class="section-fields">${extra.map(f=>fieldHTML(f,d)).join('')}</div></section>`;return out}
function setField(key,value){const field=$('#f-'+key);if(!field)return;if(value&&['tracao','carreta','carreta2','carreta3','carreta4'].includes(key)){const vehicle=state.refs.veiculos?.find(r=>String(r.id)===String(value));if(!vehicle||!vehicleMatchesSlot(key,vehicle)){toast('O tipo do veículo não é compatível com '+key+'. Selecione um veículo válido.',true);return}}field.value=value;const lookup=$(`[data-lookup="${key}"]`);if(lookup){const item=state.refs[lookup.dataset.module]?.find(r=>String(r.id)===String(value));lookup.querySelector('.lookup-text').value=item?.nome||''}if(field.type==='hidden'&&$('#date-'+key)){const parts=String(value).slice(0,16).split('T');$('#date-'+key).value=parts[0]||'';$('#time-'+key).value=parts[1]||''}field.dispatchEvent(new Event('change',{bubbles:true}));updateMargin()}
function wireLookups(){document.querySelectorAll('[data-lookup]').forEach(el=>{const key=el.dataset.lookup,hidden=el.querySelector('input[type="hidden"]'),text=el.querySelector('.lookup-text'),box=el.querySelector('.lookup-options');let focusIndex=-1,visible=[];function hide(){box.hidden=true;text.setAttribute('aria-expanded','false')}
function show(){const term=text.value.toLocaleLowerCase('pt-BR');visible=(state.refs[el.dataset.module]||[]).filter(r=>vehicleMatchesSlot(key,r,el.dataset.module)).filter(r=>!term||[r.nome,r.documento,r.cpf,r.placa,r.id].join(' ').toLocaleLowerCase('pt-BR').includes(term)).slice(0,50);focusIndex=-1;box.innerHTML=visible.length?visible.map((r,i)=>`<button type="button" role="option" data-option="${i}"><strong>${esc(r.nome)}</strong><small>#${r.id}${r.cpf?' · '+esc(r.cpf):r.documento?' · '+esc(r.documento):''}</small></button>`).join(''):'<div class="lookup-empty">Nenhum cadastro encontrado.</div>';box.hidden=false;text.setAttribute('aria-expanded','true');box.querySelectorAll('[data-option]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>choose(Number(b.dataset.option))})}
function choose(i){const r=visible[i];if(!r)return;hidden.value=r.id;text.value=r.nome;hide();hidden.dispatchEvent(new Event('change',{bubbles:true}));updateDriverHint()}
text.oninput=()=>{hidden.value='';hidden.dispatchEvent(new Event('change',{bubbles:true}));show()};text.onfocus=show;text.onblur=()=>setTimeout(hide,150);text.onkeydown=e=>{if(e.key==='Escape'){hide();return}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(box.hidden)show();focusIndex=Math.max(0,Math.min(visible.length-1,focusIndex+(e.key==='ArrowDown'?1:-1)));box.querySelectorAll('[data-option]').forEach((b,i)=>{b.classList.toggle('focused',i===focusIndex);if(i===focusIndex)b.scrollIntoView({block:'nearest'})})}if(e.key==='Enter'&&!box.hidden){e.preventDefault();choose(focusIndex>=0?focusIndex:0)}};el.querySelector('.lookup-open').onclick=()=>{text.focus();show()};el.querySelector('.lookup-clear').onclick=()=>{hidden.value='';text.value='';hide();hidden.dispatchEvent(new Event('change',{bubbles:true}));updateDriverHint()}})}
function wireDateTimes(){document.querySelectorAll('[data-datetime]').forEach(el=>el.oninput=()=>{const key=el.dataset.datetime,day=$('#date-'+key).value,hour=$('#time-'+key).value;$('#f-'+key).value=day?day+'T'+(hour||'00:00'):''});['valor_cliente','frete_agregado'].forEach(k=>{if($('#f-'+k))$('#f-'+k).addEventListener('input',updateMargin)});updateMargin()}
function updateMargin(){if(!$('#margin-value'))return;const income=Number($('#f-valor_cliente')?.value||0),offer=Number($('#f-frete_agregado')?.value||0),margin=income-offer;$('#margin-value').textContent=money(margin);$('#margin-percent').textContent=(income?margin/income*100:0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+'%'}
function updateDriverHint(){if($('#driver-hint'))$('#driver-hint').innerHTML=icon('motoristas')+' '+($('#f-motorista')?.value?'Motorista vinculado.':'Motorista ainda não vinculado.')}

function contactRowHTML(row){const v=Array.isArray(row)?row:typeof row==='object'?[row.nome||'',row.telefone||'',row.email||'']:[String(row||''),'',''];return `<div class="row-entry contact-row"><input aria-label="Nome do contato" placeholder="Nome" value="${esc(v[0])}"><input aria-label="Telefone do contato" placeholder="Telefone" value="${esc(v[1])}"><input type="email" aria-label="E-mail do contato" placeholder="E-mail" value="${esc(v[2])}"><button class="small" type="button" data-remove-row title="Remover contato">${icon('close')}</button></div>`}
function wireDriveLinks(){document.querySelectorAll('[data-open-drive]').forEach(b=>b.onclick=()=>{try{const url=new URL($('#f-'+b.dataset.openDrive).value);if(url.protocol!=='https:'||url.hostname!=='drive.google.com')throw Error();window.open(url.href,'_blank','noopener,noreferrer')}catch(e){toast('Informe um link válido de pasta do Google Drive.',true)}})}

let listFilters={},listPage=1;
function normalizeText(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').trim()}
function localDay(date=new Date()){return date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0')}
function includesText(value,term){return !term||normalizeText(value).includes(normalizeText(term))}
function documentMatch(value,term){if(!term)return true;const digits=v=>String(v??'').replace(/\D/g,'');return /^[\d.\-\/\s]+$/.test(String(term))&&digits(term)?digits(value).includes(digits(term)):includesText(value,term)}
function plateMatch(value,term){return !term||normalizeText(value).replace(/[^a-z0-9]/g,'').includes(normalizeText(term).replace(/[^a-z0-9]/g,''))}
function refSearch(m,id){const r=state.refs[m]?.find(r=>String(r.id)===String(id));return r?[r.nome,r.documento,r.cpf,r.placa,r.uf].filter(Boolean).join(' '):String(id||'')}
function searchableRecord(m,r){const parts=[r.id];for(const f of state.schema[m].fields){const v=r[f.key];if(f.type==='ref')parts.push(refSearch(f.options[0],v));else if(Array.isArray(v))parts.push(v.flat().join(' '));else parts.push(v)}return parts.join(' ')}
function filterList(m,data,f={}){let result=data.filter(r=>{if(f.q&&!includesText(searchableRecord(m,r),f.q))return false;if(f.nome&&!includesText(r.nome,f.nome))return false;if(f.documento&&!documentMatch(m==='motoristas'?r.cpf:r.documento,f.documento))return false;if(f.cidade&&!includesText(refSearch('cidades',r.cidade)+' '+(r.uf||''),f.cidade))return false;if(f.categoria&&!(r.categorias||[]).includes(f.categoria))return false;if(f.status&&r.status!==f.status)return false;if(f.placa&&!plateMatch(m==='veiculos'?r.placa:ref('veiculos',r.tracao),f.placa))return false;if(f.tipo&&r.tipo!==f.tipo)return false;if(f.proprietario){const p=state.refs.pessoas?.find(p=>String(p.id)===String(r.proprietario));if(!includesText(p?.nome,f.proprietario)&&!documentMatch(p?.documento,f.proprietario))return false}if(f.cliente&&String(r.cliente)!==f.cliente)return false;if(f.lh_trip&&!includesText(r.lh_trip,f.lh_trip))return false;if(f.ambiente&&r.ambiente!==f.ambiente)return false;if(f.situacao&&(r.situacao_operacao||r.situacao_emissao||'Rascunho')!==f.situacao)return false;if(f.documento_operacao&&!documentMatch(r.documento,f.documento_operacao))return false;if(f.meio_pagamento&&(r.meio_pagamento||'Repom')!==f.meio_pagamento)return false;if(f.oc&&String(r.oc)!==f.oc.replace(/^#/,''))return false;if(f.origem&&String(r.origem)!==f.origem)return false;if(f.destino&&String(r.destino)!==f.destino)return false;const date=String(m==='programacao'?r.carregamento:m==='oc'?r.data_oc:m==='vale_pedagio'?r.data||r.created:r.emissao||r.data||r.created||'').slice(0,10);if(f.de&&(!date||date<f.de))return false;if(f.ate&&(!date||date>f.ate))return false;if(m==='programacao'&&f.periodo){const day=localDay(),now=new Date(),end=new Date(now);if(f.periodo==='hoje'&&date!==day)return false;if(f.periodo==='semana'){const start=new Date(now);start.setDate(start.getDate()-(start.getDay()+6)%7);end.setDate(start.getDate()+6);if(date<localDay(start)||date>localDay(end))return false}if(f.periodo==='mes'&&!date.startsWith(day.slice(0,7)))return false}return true});if(m==='programacao'){const sort=f.ordenar||'proximas';result=result.slice().sort((a,b)=>sort==='cliente'?ref('pessoas',a.cliente).localeCompare(ref('pessoas',b.cliente),'pt-BR'):sort==='lh'?String(a.lh_trip||'').localeCompare(String(b.lh_trip||''),'pt-BR'):sort==='recentes'?String(b.created||'').localeCompare(String(a.created||'')):String(a.carregamento||'9999').localeCompare(String(b.carregamento||'9999')))}return result}
function listFilterHTML(m){const input=(key,label,placeholder='',type='text')=>`<label class="filter-field filter-${key}"><span>${label}</span><input name="${key}" type="${type}" placeholder="${placeholder}"></label>`,select=(key,label,options,empty='Todos')=>`<label class="filter-field filter-${key}"><span>${label}</span><select name="${key}"><option value="">${empty}</option>${options.map(o=>`<option value="${esc(Array.isArray(o)?o[0]:o)}">${esc(Array.isArray(o)?o[1]:o)}</option>`).join('')}</select></label>`,status=()=>select('status','Status',state.schema[m].fields.find(f=>f.key==='status')?.options||[...new Set(rows.map(r=>r.status).filter(Boolean))]),perPage=()=>`<label class="filter-field filter-por_pagina"><span>Por página</span><select name="por_pagina">${[10,25,50,100,200].map(n=>`<option ${n===100?'selected':''}>${n}</option>`).join('')}</select></label>`,refs=m=>(state.refs[m]||[]).map(r=>[r.id,r.nome]),dates=label=>input('de',label+' — de','','date')+input('ate',label+' — até','','date');if(m==='pessoas')return input('nome','Nome','Consultar por nome…')+input('documento','CPF/CNPJ','Documento…')+input('cidade','Cidade','Cidade ou UF…')+select('categoria','Categoria',state.schema.pessoas.fields.find(f=>f.key==='categorias').options,'Todas')+status()+perPage();if(m==='motoristas')return input('nome','Nome','Consultar por nome…')+input('documento','CPF','CPF…')+input('cidade','Cidade','Cidade ou UF…')+status()+perPage();if(m==='veiculos')return input('placa','Placa','Consultar por placa…')+select('tipo','Tipo',state.schema.veiculos.fields.find(f=>f.key==='tipo').options)+input('proprietario','Proprietário','Nome ou documento…')+status()+perPage();if(m==='programacao')return select('periodo','Período',[['hoje','Hoje'],['semana','Esta semana'],['mes','Este mês']],'Todos os períodos')+select('cliente','Cliente',refs('pessoas'))+input('lh_trip','LH Trip','Consultar LH Trip…')+status()+select('ordenar','Ordenar por',[['proximas','Próximas coletas'],['recentes','Mais recentes'],['cliente','Cliente'],['lh','LH Trip']],'Próximas coletas')+dates('Coleta')+perPage();if(m==='oc')return input('q','Pesquisar','Origem, destino, tomador, motorista ou programação…')+status()+dates('Data OC')+perPage();if(m==='mdfe'||m==='cte')return select('ambiente','Ambiente',[['Produção','1 — Produção'],['Homologação','2 — Homologação']],'Todos os ambientes')+input('q','Pesquisar','Pesquisar em '+titles[m]+'…')+perPage();if(m==='vale_pedagio')return dates('Data')+select('situacao','Situação',['Rascunho','Aguardando configuração','Em processamento','Comprado','Erro','Cancelado'],'Todas')+input('documento_operacao','Documento','Documento…')+input('placa','Placa','ABC1D23')+select('meio_pagamento','Meio de pagamento',['Repom'])+input('oc','OC','Número')+input('q','Pesquisa geral','Documento, VPO, viagem ou mensagem…')+perPage();if(m==='rotas')return input('q','Pesquisar','Descrição, percurso ou observação…')+select('origem','Origem',refs('cidades'),'Todas')+select('destino','Destino',refs('cidades'),'Todas')+status()+perPage();return input('q','Pesquisar','Pesquisar em '+titles[m]+'…')+status()+perPage()}
function listMetricsHTML(m,data){const count=s=>data.filter(r=>r.status===s).length;let metrics=[];if(m==='pessoas')metrics=[['Total cadastrado',data.length],...['Cliente','Fornecedor','Proprietário','Agenciador'].map((s,i)=>[['Clientes','Fornecedores','Proprietários','Agenciadores'][i],data.filter(r=>(r.categorias||[]).includes(s)).length])];if(m==='motoristas'){const day=localDay(),end=new Date();end.setDate(end.getDate()+30);metrics=[['Total cadastrado',data.length],['Ativos',count('Ativo')],['CNH vencidas',data.filter(r=>r.cnh_validade&&r.cnh_validade<day).length],['CNH a vencer',data.filter(r=>r.cnh_validade&&r.cnh_validade>=day&&r.cnh_validade<=localDay(end)).length]]}if(m==='veiculos')metrics=[['Total cadastrado',data.length],['Ativos',count('Ativo')],['Inativos',count('Inativo')],['Bloqueados',count('Bloqueado')]];if(m==='programacao')metrics=[['Programadas esta semana',filterList(m,data,{periodo:'semana'}).length],['Sem motorista',data.filter(r=>!r.motorista&&!['Finalizada','Cancelada'].includes(r.status)).length],['Captadas',count('Captada')],['Prontas para OC',count('Pronta para OC')],['OCs criadas',count('OC criada')],['Em carregamento',count('Em Carregamento')],['Em viagem',count('Em Viagem')],['Canceladas',count('Cancelada')]];if(m==='oc')metrics=[['Total encontrado',data.length],['Abertas',count('Aberta')],['Embarque autorizado',count('Embarque Autorizado')],['Em carregamento',count('Em Carregamento')],['Em viagem',count('Em Viagem')]];if(m==='vale_pedagio'){const situation=r=>r.situacao_operacao||r.situacao_emissao||'Rascunho';metrics=[['Total',data.length],['Em processamento',data.filter(r=>situation(r)==='Em processamento').length],['Comprados',data.filter(r=>situation(r)==='Comprado').length],['Erros / Atenção',data.filter(r=>['Erro','Aguardando configuração'].includes(situation(r))).length]]}return metrics.length?`<div class="list-metrics metrics-${metrics.length}">${metrics.map(([label,n])=>`<div class="list-metric"><span>${label}</span><strong>${n}</strong></div>`).join('')}</div>`:''}
